css:
body {
	margin: 0;
	font-family: sans-serif;
}

main.mk-1jewfs { padding: 16px; }
			.toggles.mk-1jewfs { display: flex; flex-wrap: wrap; gap: 8px; }
			.t.mk-1jewfs { padding: 8px 12px; border: 2px solid #44403c; border-radius: 8px; background: #f5f5f4; color: #1c1917; font-family: inherit; font-size: 16px; }
			.t.on.mk-1jewfs { border-color: #166534; background: #dcfce7; color: #14532d; }
			.status.mk-1jewfs { margin: 8px 0 0; color: #44403c; }
			.stage.mk-1jewfs { height: 160px; margin-top: 16px; }
			.panel.mk-1jewfs { position: absolute; left: 16px; top: 220px; width: 240px; height: 120px; z-index: 2; background: #bfdbfe; }
			.note.mk-1jewfs { position: absolute; left: 96px; top: 260px; width: 200px; height: 64px; z-index: 3; background: #fde68a; }
			.fill.mk-1jewfs { display: block; width: 100%; height: 100%; padding: 0; border: 0; background: transparent; font-family: inherit; font-size: 16px; }
			.panel .fill.mk-1jewfs { color: #1e3a8a; text-align: left; }
			.note .fill.mk-1jewfs { color: #78350f; }
